"""
Base Abstract Provider for Large Language Models.
"""

from __future__ import annotations
from abc import ABC, abstractmethod
from typing import List, Dict, Any, Optional
from pydantic import BaseModel


class ToolCallRequest(BaseModel):
    """Normalized tool call request generated by an LLM."""
    id: str
    name: str
    arguments: Dict[str, Any]


class ProviderStepResponse(BaseModel):
    """Normalized step response from an LLM."""
    thought: str
    tool_calls: List[ToolCallRequest]
    stop_reason: str
    prompt_tokens: int
    completion_tokens: int
    cached_tokens: int = 0
    raw_message: Any = None


class BaseLLMProvider(ABC):
    """Abstract interface for LLM model providers."""

    def __init__(self, model_name: str):
        self.model_name = model_name

    @abstractmethod
    def generate_step(
        self,
        messages: List[Dict[str, Any]],
        tools: List[Dict[str, Any]],
        system_prompt: str,
        temperature: float = 0.1,
    ) -> ProviderStepResponse:
        """Executes a single reasoning turn and yields thoughts and optional tool calls."""
        pass

    @abstractmethod
    def generate_final_report(
        self,
        messages: List[Dict[str, Any]],
        system_prompt: str,
    ) -> tuple[str, int, int]:
        """Synthesizes the final structured report. Returns (report_text, prompt_tokens, completion_tokens)."""
        pass
